from PyQt5.uic import loadUi

from PyQt5.QtWidgets import QApplication

from numpy import *

tn = array([int] * 999)

tm = array([int] * 999)


def verif(ch1, ch2):
    if ch1 != '' and ch1.isnumeric() and ch2.isnumeric():
        if 10 <= int(ch1) < int(ch2) <= 999:
            return True
        else:
            return False
    else:
        return False


def Somme_div(n):
    S = 0
    d = 1
    while d < n:
        if n % d == 0:
            S += d
            d += 1
        else:
            d += 1
    return S


def Suite_aliquote(a, t):
    t[0] = a
    i = 1
    while a != 1:
        a = Somme_div(a)
        t[i] = a
        i += 1
    return i


def commun(tn, tm, j, k):
    S = 0
    for i in range(j):
        for loop in range(k):
            if (tn[i]) == tm[loop]:
                S += 1
    return S


def Traitement(a, b, tn, tm):
    if verif(a, b):
        n = int(a)
        m = int(b)
        j = Suite_aliquote(n, tn)
        k = Suite_aliquote(m, tm)
        S = commun(tn, tm, j, k)
        chn = ''
        chm = ''
        for i in range(j):
            chn += str(tn[i]) + '/'
        for i in range(k):
            chm += str(tm[i]) + '/ '
        p.t1.setText(chn[:len(chn) - 1])
        p.t2.setText(chm[:len(chm) - 2])
        p.t3.setText(str(S))

    else:
        p.t1.setText('INPUT ERROR')
        p.t2.setText('INPUT ERROR')


def Annuler():
    p.t1.setText('')
    p.t2.setText('')
    p.t3.setText('')
    p.l1.setText('')
    p.l1.setText('')
    p.l2.setFocus()


def Fermer():
    p.close()


app = QApplication([])
p = loadUi('epreuve_pratique_2014_sujet5_interface.ui')
p.show()
p.pb1.clicked.connect(lambda: Traitement(p.l1.text(), p.l2.text(), tn, tm))
p.pb2.clicked.connect(Annuler)
p.pb3.clicked.connect(Fermer)
app.exec_()

